parameters.query:
SELECT u.id AS user_id, u.email, u.company_name, u.language, u.trade, u.region,
  coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.score DESC) FROM match_tenders(u.id, 3) m), '[]'::jsonb) AS tenders
FROM users u WHERE u.id = $1::uuid;

parameters.jsCode:
const APP_BASE_URL = 'https://app.example.com';        // TODO: your product deep-link base
const inp = $('Input').item.json;
const row = $('Load user & matches').item.json;
const tenders = row.tenders;
const lang = row.language === 'en' ? 'en' : 'de';
const locale = lang === 'de' ? 'de-DE' : 'en-GB';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid4 = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random()*16|0; return (c==='x'?r:(r&0x3|0x8)).toString(16); });
const digestId = uuid4();

// ---- 1) validate LLM copy, else deterministic fallback --------------------------------
const o = $json.output;
let copy = null, source = 'fallback';
if (o && typeof o.subject === 'string' && o.subject.length > 0 && o.subject.length <= 70
    && typeof o.intro === 'string' && Array.isArray(o.reasons)) {
  const ids = new Set(tenders.map(t => t.tender_id));
  const why = {};
  for (const r of o.reasons) {
    if (ids.has(r.tender_id) && typeof r.why_it_fits === 'string' && r.why_it_fits.length <= 200) why[r.tender_id] = r.why_it_fits;
  }
  if (Object.keys(why).length === tenders.length) {
    copy = { subject: o.subject, preheader: o.preheader || '', intro: o.intro, why };
    source = 'llm';
  }
}
const L = lang === 'de'
  ? { cta: 'Ausschreibung ansehen', deadline: 'Frist', value: 'Volumen', left: d => `noch ${Math.max(0, Math.round(d))} Tage`,
      subject: n => `${n} passende Ausschreibungen für Ihr Gewerk`, pre: 'Ausgewählt nach Gewerk, Region und Frist.',
      intro: `Diese offenen Ausschreibungen passen zu ${row.trade} in Ihrer Region:`,
      why: r => `Passt zu Ihrem Gewerk${r.region_match ? ' und Ihrer Region' : ''}, Frist in ${Math.round(r.days_left)} Tagen.` }
  : { cta: 'View tender', deadline: 'Deadline', value: 'Value', left: d => `${Math.max(0, Math.round(d))} days left`,
      subject: n => `${n} open tenders that match your trade`, pre: 'Picked by trade, region and deadline.',
      intro: `These open tenders match ${row.trade} work in your area:`,
      why: r => `Matches your trade${r.region_match ? ' and region' : ''}, ${Math.round(r.days_left)} days to bid.` };
if (!copy) {
  const why = {}; tenders.forEach(t => why[t.tender_id] = L.why(t.reasons));
  copy = { subject: L.subject(tenders.length), preheader: L.pre, intro: L.intro, why };
}

// ---- 2) deterministic HTML render ---------------------------------------------------------
const fmtDate = d => new Date(d).toLocaleDateString(locale, { day: '2-digit', month: 'short', year: 'numeric' });
const fmtEur = v => new Intl.NumberFormat(locale, { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Number(v));
const link = t => `${APP_BASE_URL}/tenders/${t.tender_id}?utm_source=nba&utm_medium=email&utm_campaign=tender_digest&utm_content=${digestId}`;
const cards = tenders.map(t => `
<tr><td style="padding:0 0 16px 0">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e3e6ea;border-radius:8px">
    <tr><td style="padding:16px 18px;font-family:Arial,Helvetica,sans-serif">
      <div style="font-size:16px;font-weight:bold;color:#14213d">${esc(t.title)}</div>
      <div style="font-size:13px;color:#5b6573;margin:4px 0 10px">${esc(t.trade)} · ${esc(t.region)} · ${L.deadline}: ${fmtDate(t.deadline)} (${L.left(t.reasons.days_left)}) · ${L.value}: ${fmtEur(t.value_eur)}</div>
      <div style="font-size:14px;color:#222;margin:0 0 14px">${esc(copy.why[t.tender_id])}</div>
      <a href="${link(t)}" style="display:inline-block;background:#14213d;color:#ffffff;text-decoration:none;font-size:14px;padding:9px 16px;border-radius:6px">${L.cta}</a>
    </td></tr>
  </table>
</td></tr>`).join('');
const html = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%">
<tr><td style="padding:0 0 16px 0;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#222">${esc(copy.intro)}</td></tr>${cards}
</table></td></tr></table>`;

return { json: {
  user_id: row.user_id, email: row.email, digest_id: digestId, copy_source: source,
  subject: copy.subject, preheader: copy.preheader, html,
  tender_ids: tenders.map(t => t.tender_id),
  match_scores: tenders.map(t => ({ tender_id: t.tender_id, score: t.score, reasons: t.reasons })),
  ab_variant: inp.ab_variant || null, message_angle: inp.message_angle || null
}};
